representation.shell_command:
set +e
exec > probe.txt 2>&1
PIP_USER=0 python3 -m pip install --no-cache-dir --target "$PWD/.deps" pip==21.3.1
echo pip_bootstrap=$?
export PYTHONPATH="$PWD/.deps"
PIP_USER=0 python3 -m pip install --no-cache-dir --target "$PWD/.deps" miniwdl==1.12.0
echo miniwdl_install=$?
export PATH="$PWD/.deps/bin:$PATH"
miniwdl --version 2>&1
cat > tiny.wdl <<'WDL'
version 1.0
workflow tiny {
  input { File input }
  call make_file { input: input=input }
  output { File out = make_file.out }
}
task make_file {
  input { File input }
  command {
    echo hello > out.txt
    wc -c "${input}" > size.txt
    cat size.txt >> out.txt
  }
  output { File out = 'out.txt' }
  runtime { cpu: 1; memory: '1 GB' }
}
WDL
printf '%s' '{"tiny.input":"'$(inputs.input.path)'"}' > tiny.json
cat tiny.json
miniwdl run --dir run_out tiny.wdl -i tiny.json 2>&1 | head -200
echo run_rc=${PIPESTATUS[0]}
find run_out -maxdepth 4 -type f -printf '%p %s\n' | sort | head -100
exit 0

